def validate(data):
    ne = json.load(open(NE))["features"]
    codes = {}
    for f in ne:
        p = f["properties"]
        codes.setdefault(p["adm0_a3"], set()).add(p["iso_3166_2"])
    problems = []
    for c in data:
        have = codes.get(ADM0.get(c["iso3"], c["iso3"]), set())
        seen = set()
        for u in c["units"]:
            comp = u.get("component_codes")
            if comp:
                problems += [f"{c['iso3']} {u['name']}: component {k} not in NE" for k in comp if k not in have]
            elif u["code"] not in have:
                problems.append(f"{c['iso3']} {u['name']}: code {u['code']} not in NE")
            if u["code"] in seen: problems.append(f"{c['iso3']}: duplicate unit code {u['code']}")
            seen.add(u["code"])
            ys = [s["year"] for s in u["series"]]
            if len(ys) != len(set(ys)): problems.append(f"{c['iso3']} {u['name']}: duplicate years")
            for s in u["series"]:
                if not isinstance(s["year"], int): problems.append(f"{u['name']}: year not int")
                if not (0.3 <= s["tfr"] <= 9): problems.append(f"{u['name']} {s['year']}: tfr {s['tfr']} out of range")
                if s["kind"] not in ("official", "survey", "estimate"): problems.append(f"{u['name']}: bad kind")
    return problems


if __name__ == "__main__":
    probs = validate(DATA)
    for p in probs: print("PROBLEM:", p)
    assert not probs
    json.dump(DATA, open(OUT, "w"), ensure_ascii=False, indent=1)
    back = json.load(open(OUT))
    for c in back:
        ys = sorted({s["year"] for u in c["units"] for s in u["series"]})
        print(f"{c['iso3']}: {len(c['units'])} units, years {ys[0]}-{ys[-1]} ({len(ys)} distinct), {sum(len(u['series']) for u in c['units'])} values")
    print("wrote", OUT)
